<div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="page-title">Ubicaciones de puntos de control</h1><p class="page-description">Corrige las coordenadas referenciales para mejorar la ubicación del punto en el mapa.</p></div><a href="<?= e(url('/mapa-presion')) ?>" class="button-secondary"><i class="bi bi-map" aria-hidden="true"></i>Ver mapa</a></div>
<section class="panel mt-7"><div class="mb-5"><h2 class="section-title">Coordenadas</h2><p class="mt-1 text-sm text-slate-500">Al guardar una coordenada, el punto deja de mostrarse como referencial.</p></div><div><table class="data-table min-w-[1180px]" data-search-placeholder="Buscar código, dirección, zona o sector..."><thead><tr><th>Código</th><th>Dirección</th><th>Zona geográfica</th><th>Sector / zona</th><th>Origen</th><th class="text-right">Latitud</th><th class="text-right">Longitud</th><th class="text-right">Acción</th></tr></thead><tbody><?php foreach ($puntos as $punto): ?><tr><th scope="row" class="font-semibold text-slate-900"><?= e($punto['codigo']) ?></th><td><?= e($punto['direccion']) ?></td><td class="font-medium text-slate-900"><?= e($punto['zona_geografica']) ?></td><td><?= e($punto['sector'] . ' · ' . $punto['zona_presion']) ?></td><td><span class="status-chip <?= (int) $punto['coordenadas_referenciales'] === 1 ? 'estado-en_revision' : 'estado-aprobado' ?>"><?= (int) $punto['coordenadas_referenciales'] === 1 ? 'Referencial' : 'Validada' ?></span></td><td class="text-right tabular-nums"><?= number_format((float) $punto['latitud'], 7, '.', '') ?></td><td class="text-right tabular-nums"><?= number_format((float) $punto['longitud'], 7, '.', '') ?></td><td class="text-right"><details class="inline-block text-left"><summary class="button-secondary cursor-pointer list-none"><i class="bi bi-pencil" aria-hidden="true"></i>Editar</summary><form method="post" action="<?= e(url('/mapa-presion/ubicaciones')) ?>" class="mt-3 grid min-w-72 gap-3 rounded-lg border border-slate-200 bg-white p-3 shadow-lg"><input type="hidden" name="token" value="<?= e($tokenFormulario) ?>"><input type="hidden" name="punto_id" value="<?= (int) $punto['id'] ?>"><label class="form-label text-xs">Latitud<input class="field mt-1" type="number" name="latitud" step="0.0000001" value="<?= number_format((float) $punto['latitud'], 7, '.', '') ?>" required></label><label class="form-label text-xs">Longitud<input class="field mt-1" type="number" name="longitud" step="0.0000001" value="<?= number_format((float) $punto['longitud'], 7, '.', '') ?>" required></label><button class="button-primary justify-center" type="submit">Guardar ubicación</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></section>
